var main=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/MountainPass/MountainPass.unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);
var p=main.GetRootGameObjects().SelectMany(o=>o.GetComponentsInChildren<Cheon.Prototype.MountainPass.PassPlayerMovement>(true)).Single();
var a=p.AnimationControl;
return new {root=p.name,pos=new[]{p.transform.position.x,p.transform.position.y,p.transform.position.z},animator=a.CharacterAnimator.name,animatorParent=a.CharacterAnimator.transform.parent.name,animatorLocalPos=new[]{a.CharacterAnimator.transform.localPosition.x,a.CharacterAnimator.transform.localPosition.y,a.CharacterAnimator.transform.localPosition.z},scale=new[]{a.CharacterAnimator.transform.lossyScale.x,a.CharacterAnimator.transform.lossyScale.y,a.CharacterAnimator.transform.lossyScale.z},boss=main.GetRootGameObjects().SelectMany(o=>o.GetComponentsInChildren<Cheon.Prototype.MountainPass.PassBossController>(true)).Select(b=>new{b.name,type=b.GetType().FullName}),controller=AssetDatabase.GetAssetPath(a.CharacterAnimator.runtimeAnimatorController),timings=AssetDatabase.GetAssetPath(a.SavedTimings),dirty=main.isDirty};
